/// <summary>
/// PricingAttribute of table <c>CustTable</c> field SegmentId.
/// </summary>
[GUPPricingMetadataDiscovery][GUPPricingAttributeSourceDiscovery(GUPPricingAttributeSource::Customer, GUPPricingAttributeSourceLevel::Header)]
[GUPPricingAttributeFieldsDiscovery(fieldStr(CustTable, SegmentId))]
internal class GUPPricingAttributeCustTableSegmentId extends GUPPricingAttributeCustTable implements GUPIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(CustTable, SegmentId);
}

public Set getAllowedValuesWithDescription()
{
    var ret = new Set(Types::AnyType);

    Custtable                custTable;
    smmBusRelSegmentGroup    smmBusRelSegmentGroup;

    while select SegmentId from custtable
        group by SegmentId
        join smmBusRelSegmentGroup
        group by SegmentId, Description
        where custTable.SegmentId == smmBusRelSegmentGroup.SegmentId
    {
        GUPPricingAttributeAllowedValuesObject valueObject =
            new GUPPricingAttributeAllowedValuesObject(smmBusRelSegmentGroup.SegmentId, smmBusRelSegmentGroup.Description);
        ret.add(valueObject);
    }
    return ret;
}
